import * as THREE from 'three/webgpu';
import { uniform, texture, uv, vec2, vec3, float, mix, MeshPhysicalNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'FilmstripCarousel';
  group.position.set(0, 0, 0);

  const IMG_URL = '/prism-mock/home/nodes/parallax-stack.png';
  const baseTex = ctx.textureLoader.load(IMG_URL);
  baseTex.colorSpace = THREE.SRGBColorSpace;

  const CARD_W = 1.6, CARD_H = 1.0, PITCH = 1.85, COUNT = 5;
  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  const strip = new THREE.Group();
  strip.rotation.y = THREE.MathUtils.degToRad(-18);
  group.add(strip);

  const uvShiftUniforms = [];
  const cardMeshes = [];
  const focusIndex = 2; // middle card, x=0

  const geo = new THREE.PlaneGeometry(CARD_W, CARD_H);
  const bevelGeo = new THREE.PlaneGeometry(CARD_W + 0.05, CARD_H + 0.05);

  for (let i = 0; i < COUNT; i++) {
    const cardGroup = new THREE.Group();
    const xPos = (i - focusIndex) * PITCH;
    cardGroup.position.x = xPos;

    // bevel frame behind card
    const bevelMat = new MeshPhysicalNodeMaterial();
    bevelMat.colorNode = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
    bevelMat.roughness = 0.6;
    bevelMat.metalness = 0.3;
    const bevelMesh = new THREE.Mesh(bevelGeo, bevelMat);
    bevelMesh.position.z = -0.005;
    cardGroup.add(bevelMesh);

    const uvShift = uniform(vec2(0, 0));
    uvShiftUniforms.push(uvShift);

    const opacityUniform = uniform(1.0);
    const mat = new MeshPhysicalNodeMaterial();
    const uvNode = uv().add(uvShift);
    mat.colorNode = texture(baseTex, uvNode);
    mat.roughness = 0.55;
    mat.metalness = 0.2;
    mat.clearcoat = 0.15;
    mat.transparent = true;
    mat.opacityNode = opacityUniform;

    const cardMesh = new THREE.Mesh(geo, mat);
    cardGroup.add(cardMesh);

    const isFocused = i === focusIndex;
    cardGroup.rotation.y = isFocused ? THREE.MathUtils.degToRad(18) : 0;
    const scale = isFocused ? 1.0 : 0.92;
    cardGroup.scale.set(scale, scale, scale);

    const dist = Math.abs(i - focusIndex);
    opacityUniform.value = Math.max(0.55, 1.0 - dist * 0.15);

    strip.add(cardGroup);
    cardMeshes.push({ cardGroup, mat, opacityUniform, isFocused });

    // caption text per card
    if (ctx.fontAtlas && ctx.fontAtlas.createText) {
      const captionText = ctx.fontAtlas.createText(captions[i], {
        fontFamily: 'JetBrains Mono',
        fontSize: 18,
        fontWeight: 700,
        letterSpacing: 0.08,
        lineHeight: 1.4,
        color: '#e8ecf2',
      });
      captionText.position.set(0, -CARD_H / 2 - 0.15, 0.01);
      cardGroup.add(captionText);
    }
  }

  // focused underline bar
  const barGeo = new THREE.PlaneGeometry(1.6, 0.035);
  const barMat = new MeshPhysicalNodeMaterial();
  barMat.colorNode = vec3(1.0, 0x2a / 255, 0x38 / 255);
  barMat.emissiveNode = vec3(1.0, 0.16, 0.22).mul(float(1.3));
  const barMesh = new THREE.Mesh(barGeo, barMat);
  const focusedGroup = cardMeshes[focusIndex].cardGroup;
  barMesh.position.set(0, -CARD_H / 2 - 0.06, 0.02);
  focusedGroup.add(barMesh);

  // headline + body text
  let headlineText = null;
  let bodyText = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    headlineText = ctx.fontAtlas.createText('The collection', {
      fontFamily: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1,
      color: '#e8ecf2',
    });
    headlineText.position.set(-2.6, 1.5, 0);
    group.add(headlineText);

    bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
      fontFamily: 'JetBrains Mono',
      fontSize: 26,
      fontWeight: 400,
      letterSpacing: 0,
      lineHeight: 1.5,
      color: '#e8ecf2',
    });
    bodyText.position.set(-2.6, -1.5, 0);
    group.add(bodyText);
  }

  // lights
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);
  const ambLight = new THREE.AmbientLight(0x404050, 0.6);
  group.add(ambLight);

  // apply cinematic primitives
  const primitiveList = config.cinematicPrimitives || [];
  for (const prim of primitiveList) {
    if (ctx.primitives && ctx.primitives[prim.name]) {
      ctx.primitives[prim.name](strip, prim.params);
    }
  }

  // scroll-based parallax + snap
  let scrollAccum = 0;
  let snapTween = null;
  const intensity = 0.5;

  function onScroll(deltaScrollUnits) {
    scrollAccum += deltaScrollUnits;
    const targetX = scrollAccum * intensity;
    strip.position.x = targetX;
    for (let i = 0; i < uvShiftUniforms.length; i++) {
      const dir = i % 2 === 0 ? 1 : -1;
      uvShiftUniforms[i].value.x = dir * 0.04 * Math.sin(scrollAccum * 0.5);
    }
    if (snapTween) snapTween.kill();
    snapTween = gsap.delayedCall(0.15, () => {
      const nearestIndex = Math.round(-strip.position.x / PITCH);
      const snapX = -nearestIndex * PITCH * intensity;
      gsap.to(strip.position, {
        x: snapX,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      });
      gsap.fromTo(strip.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    });
  }

  group.userData.handlers = {
    onScroll,
  };

  group.userData.cleanup = () => {
    if (snapTween) snapTween.kill();
    gsap.killTweensOf(strip.position);
    gsap.killTweensOf(strip.scale);
    geo.dispose();
    bevelGeo.dispose();
    barGeo.dispose();
    cardMeshes.forEach(({ mat }) => mat.dispose());
    bevelMat.dispose();
    barMat.dispose();
    baseTex.dispose();
    if (headlineText && headlineText.userData && headlineText.userData.dispose) headlineText.userData.dispose();
    if (bodyText && bodyText.userData && bodyText.userData.dispose) bodyText.userData.dispose();
    cardMeshes.forEach(({ cardGroup }) => {
      cardGroup.traverse((child) => {
        if (child.userData && child.userData.dispose) child.userData.dispose();
      });
    });
  };

  return group;
}
